import json, re

def check_output(raw):
    try:
        data = json.loads(raw)
    except ValueError:
        return ['invalid json']
    if not isinstance(data, dict):
        return ['invalid json']
    problems = []
    if data.get('category') not in ('billing', 'technical', 'account'):
        problems.append('category')
    p = data.get('priority')
    if isinstance(p, bool) or not isinstance(p, int) or not 1 <= p <= 3:
        problems.append('priority')
    s = data.get('summary')
    if not isinstance(s, str) or not 1 <= len(s) <= 200:
        problems.append('summary')
    elif re.search(r'[\w.+-]+@[\w-]+\.[\w.]+', s):
        problems.append('pii')
    return sorted(problems)

